mapper.select:
select msi.layer_name as layerName, mfi.resource_crs as resourceSrs, mfi.tile_extension as resourceFormat, mfi.tile_width as tileWidth, mfi.tile_height as tileHeight, msi.file_url as filePath, msi.file_type as fileType, msi.data_type as dataType, mfi.zoom_level as supportMaxLevel, msi.server_status as status, msi.pulished_proctol as supportProtocal, mfi.resource_bbox as resourceBbox, mfi.resource_crs as resourceSrs, mfi.native_bbox as nativaBbox, mfi.tile_origin_flag as origin, msi.is_layer_group as isLayerGroup, style_info.style_name as styleName from map_server_info msi left join map_feature_info mfi on msi.server_id = mfi.server_id left join server_style_info ssi on ssi.server_id = msi.server_id left join style_info on style_info.id = ssi.style_id where 1 = 1
and msi.layer_name = #{serverName}
and msi.pulished_proctol ~* #{protocolName}
and msi.is_public = 1
